using OutreachFlow.Api.Errors; using OutreachFlow.Application.Campaigns;
namespace OutreachFlow.Api.Endpoints;
public static class CampaignEndpoints { public static IEndpointRouteBuilder MapCampaignEndpoints(this IEndpointRouteBuilder endpoints) { var group=endpoints.MapGroup("/api/v1/campaigns").WithTags("Campaigns"); group.MapGet("",async(ICampaignService s,CancellationToken ct)=>await ApiEndpoint.HandleAsync(async()=>Results.Ok(await s.ListAsync(ct)))).WithOpenApi(); group.MapPost("",async(CreateCampaignRequest r,ICampaignService s,CancellationToken ct)=>await ApiEndpoint.HandleAsync(async()=>{var item=await s.CreateAsync(r,ct);return Results.Created($"/api/v1/campaigns/{item.Id}",item);})).WithOpenApi(); group.MapGet("/{id:guid}",async(Guid id,ICampaignService s,CancellationToken ct)=>await ApiEndpoint.HandleAsync(async()=>Results.Ok(await s.GetAsync(id,ct)))).WithOpenApi(); group.MapPut("/{id:guid}",async(Guid id,UpdateCampaignRequest r,ICampaignService s,CancellationToken ct)=>await ApiEndpoint.HandleAsync(async()=>Results.Ok(await s.UpdateAsync(id,r,ct)))).WithOpenApi(); group.MapPost("/{id:guid}/drafts",async(Guid id,ICampaignDraftGenerationService s,CancellationToken ct)=>await ApiEndpoint.HandleAsync(async()=>Results.Ok(new { generatedDrafts = await s.GenerateAsync(id,ct) }))).WithOpenApi(); group.MapDelete("/{id:guid}",async(Guid id,ICampaignService s,CancellationToken ct)=>await ApiEndpoint.HandleAsync(async()=>{await s.DeleteAsync(id,ct);return Results.NoContent();})).WithOpenApi(); return endpoints; } }
